//! Typography, spacing and the palette shared by every surface.
//!
//! Herse's design language (see DESIGN.md): a notebook is a page. Warm
//! paper and ink, Charter for prose, SF Mono for code, and one accent, dew,
//! for where you are and what is live. The palette is a GPUI Kit theme set
//! (`assets/herse-theme.json`, generated by `assets/make_theme.py`) so light
//! and dark both work; other colour is kept for information: syntax, charts,
//! errors.

use gpui_kit::component::ActiveTheme as _;
use gpui_kit::{Hsla, Pixels, hsla, px};

/// Dew, the one accent: the selected cell's margin bar, the editor's
/// outline, focus, the caret, links. (The theme's `primary`.)
pub fn accent(cx: &gpui_kit::App) -> Hsla {
    cx.theme().primary
}

/// A notebook's file icon: Jupyter's orange, softened to sit on the paper
/// (and lifted on the dark page). The one other hue in the tree, next to
/// dew's teal.
pub fn notebook_icon(cx: &gpui_kit::App) -> Hsla {
    if cx.theme().is_dark() {
        gpui_kit::hsla(28. / 360., 0.72, 0.64, 1.)
    } else {
        gpui_kit::hsla(24. / 360., 0.68, 0.50, 1.)
    }
}

use std::sync::OnceLock;

pub const UI_FONT: &str = ".SystemUIFont";

static MONO: OnceLock<&'static str> = OnceLock::new();

/// The code font: SF Mono when we can load it (it ships with macOS but isn't
/// registered as a family for apps), otherwise Menlo.
pub fn mono_font() -> &'static str {
    MONO.get().copied().unwrap_or("Menlo")
}

static PROSE: OnceLock<&'static str> = OnceLock::new();

/// Markdown prose: Charter, a serif made for reading on screens (it ships
/// with macOS), else the UI font. Notebooks read like papers.
pub fn prose_font() -> &'static str {
    PROSE.get().copied().unwrap_or(UI_FONT)
}

/// Markdown body text. A serif needs a point more than the sans around it.
pub fn prose_size() -> Pixels {
    px(15. * zoom())
}

pub fn load_fonts(cx: &mut gpui_kit::App) {
    {
        let ts = cx.text_system();
        let missing = ts.resolve_font(&gpui_kit::font("Herse Missing Font Probe"));
        if ts.resolve_font(&gpui_kit::font("Charter")) != missing {
            let _ = PROSE.set("Charter");
        }
    }
    // SF Mono ships with macOS but isn't registered for apps; register its
    // files, then find the family name it came up under. A name that resolves
    // to the same font as a nonsense name wasn't found. (A handful of lookups;
    // enumerating every family would cost ~100 ms at launch.)
    let files = [
        "/System/Library/Fonts/SFNSMono.ttf",
        "/System/Library/Fonts/SFNSMonoItalic.ttf",
    ];
    let fonts: Vec<_> = files
        .iter()
        .filter_map(|f| std::fs::read(f).ok())
        .map(std::borrow::Cow::Owned)
        .collect();
    if fonts.is_empty() || cx.text_system().add_fonts(fonts).is_err() {
        return;
    }
    let ts = cx.text_system();
    let missing = ts.resolve_font(&gpui_kit::font("Herse Missing Font Probe"));
    if let Some(name) = ["SF Mono", ".SF NS Mono", "SF NS Mono", ".SFNSMono"]
        .into_iter()
        .find(|n| ts.resolve_font(&gpui_kit::font(*n)) != missing)
    {
        let _ = MONO.set(name);
    }
}

/// Install Herse Light / Herse Dark as the themes light and dark mode use.
pub fn install_theme(cx: &mut gpui_kit::App) {
    use gpui_kit::component::{Theme, ThemeRegistry};
    if ThemeRegistry::global_mut(cx)
        .load_themes_from_str(include_str!("../assets/herse-theme.json"))
        .is_err()
    {
        return;
    }
    let themes = ThemeRegistry::global(cx).themes();
    let (Some(light), Some(dark)) = (themes.get("Herse Light").cloned(), themes.get("Herse Dark").cloned()) else {
        return;
    };
    let theme = cx.global_mut::<Theme>();
    theme.light_theme = light;
    theme.dark_theme = dark;
    let mode = theme.mode;
    Theme::change(mode, None, cx);
}

pub const UI_SIZE: Pixels = px(13.);

/// Content zoom (Cmd +/-): scales notebook text, code, tables and figures;
/// window chrome stays put. Stored as f32 bits for lock-free reads in render.
static ZOOM_BITS: std::sync::atomic::AtomicU32 = std::sync::atomic::AtomicU32::new(0x3f80_0000); // 1.0

pub fn zoom() -> f32 {
    f32::from_bits(ZOOM_BITS.load(std::sync::atomic::Ordering::Relaxed))
}

pub fn set_zoom(z: f32) {
    let z = (z * 20.).round() / 20.;
    ZOOM_BITS.store(z.clamp(0.6, 2.2).to_bits(), std::sync::atomic::Ordering::Relaxed);
}

/// Body text of Markdown and rich outputs.
pub fn content_size() -> Pixels {
    px(14. * zoom())
}

pub fn mono_size() -> Pixels {
    px(12.5 * zoom())
}

/// Code and stream output share one line height so a cell's static view and
/// its editor are the same height: switching modes must not move anything.
pub fn mono_line_height() -> Pixels {
    px((19. * zoom()).round())
}

