pub fn error_color(dark: bool) -> Hsla {
    if dark {
        hsla(0. / 360., 0.75, 0.68, 1.)
    } else {
        hsla(0. / 360., 0.70, 0.45, 1.)
    }
}

/// Changes since the last commit, in the margin: a cell added (green) or
/// changed (amber). Removed cells take the error red.
pub fn added_color(dark: bool) -> Hsla {
    if dark {
        hsla(140. / 360., 0.42, 0.56, 1.)
    } else {
        hsla(140. / 360., 0.48, 0.38, 1.)
    }
}

pub fn changed_color(dark: bool) -> Hsla {
    if dark {
        hsla(40. / 360., 0.78, 0.60, 1.)
    } else {
        hsla(36. / 360., 0.85, 0.47, 1.)
    }
}

pub fn error_background(dark: bool) -> Hsla {
    if dark {
        hsla(0. / 360., 0.60, 0.50, 0.10)
    } else {
        hsla(0. / 360., 0.80, 0.55, 0.07)
    }
}
